def main(api):
    evidence = []; D = {}; handles = []; tol = 0.003
    camera_names = ["agentview", "robot0_eye_in_hand"]
    pixel = {"type": "array", "items": {"type": "integer", "minimum": 0, "maximum": 767}, "minItems": 2, "maxItems": 2}
    def array(item, n, m=None):
        return {"type": "array", "items": {"type": item, "maxLength": 400} if isinstance(item, str) else item, "minItems": n, "maxItems": n if m is None else m}
    def plain(value):
        if isinstance(value, np.ndarray): return value.tolist()
        if isinstance(value, (np.floating, np.integer, np.bool_)): return value.item()
        if isinstance(value, dict): return {k: plain(v) for k, v in value.items()}
        if isinstance(value, (list, tuple)): return [plain(v) for v in value]
        return value
    def log(kind, value):
        evidence.append({"kind": kind, "value": plain(value)})
        api.note(str(evidence[-1]))
    def stop(reason):
        raise RuntimeError(reason)
    def save(phase=None):
        if phase is not None: D["phase"] = phase
        api.checkpoint("cream_method", plain(D))
    def review(question, fields, context=None):
        if api.state()["budgets"]["gpt_remaining"] < 1: stop("No observation review budget remains.")
        r = api.review(question, context=plain(context), fields=fields)
        log("review", {"frame": r["frame_id"], "parameters": r["parameters"], "errors": r["measurement_errors"], "explanation": r["explanation"]})
        if r["status"] == "stop": stop("Observation reviewer stopped: " + r["explanation"])
        return r
    def points(r, names):
        missing = [n for n in names if n not in r["points"]]
        if missing: stop("Missing current depth measurements: " + str(missing) + "; errors=" + str(r["measurement_errors"]))
        return np.array([r["points"][n]["world_m"] for n in names], dtype=float)
    questions = {}
    for axis in ["x", "y", "z", "rx", "ry", "rz"]:
        questions[axis] = {"type": "choice", "instructions": "For world axis " + axis + ", read state.processed_features.axes." + axis + ".goal_relation. Choose positive for increase, negative for decrease, hold for within_tolerance. Do not infer direction from the image or another axis.", "criteria": {"negative": "This axis requires decrease.", "hold": "This axis is within tolerance.", "positive": "This axis requires increase."}}
    questions["gripper"] = {"type": "choice", "instructions": "Read state.processed_features.objective.gripper and deliver exactly that requested gripper operation.", "criteria": {"open": "The objective requests open.", "close": "The objective requests close.", "keep": "The objective requests keep."}}
    def pulse(grip, count=3):
        s = api.state(); p = geo.pad_position(s); q = s["tcp_quaternion_xyzw"]
        for k in range(count):
            if api.state()["budgets"]["jev_remaining"] < 1 or api.state()["budgets"]["native_steps_remaining"] < 3: stop("No Jev budget for contact transition.")
            r = api.control(p.tolist(), q, grip, questions, features={"phase": D.get("phase"), "purpose": "Observe physical contact or settling, not infer it from a command."}, tool_point="pad_center", translation_limit=0.005, rotation_limit=0.04, steps=3, position_tolerance=tol, rotation_tolerance=0.05)
            if r["status"] not in ["reached", "moved"] or r["position_error_m"] > 0.009 or r["choices"]["gripper"] != grip: stop("Contact pulse failed: " + str(r))
    def register():
        for h in handles:
            t = api.track_update(h)
            if t["status"] == "tracked":
                cloud = np.array(t["reference_inlier_world_m"]); spread = np.sort(np.linalg.svd(cloud-cloud.mean(axis=0), compute_uv=False)/math.sqrt(max(1,len(cloud))))
                u = max(0.002, float(t["uncertainty_floor_m"]), 2 * float(t["rms_m"]))
                if t["inliers"] >= 12 and t["inliers"] / max(1, t["matches"]) >= 0.6 and t["rms_m"] <= 0.0025 and u <= 0.005 and len(spread) >= 2 and spread[-2] >= 0.003:
                    T = np.array(t["transform_initial_world_to_current_world"])
                    P = geo.transform(np.array(D["P"]), T)
                    return {"P": P.tolist(), "T": T.tolist(), "u": u, "frame": t["frame_id"], "source": "RGB-D rigid patch", "reference_frame": t["reference_frame_id"], "inliers": t["inliers"], "rms": t["rms_m"]}
            log("registration", {"status": t["status"], "frame": t["frame_id"], "reason": t.get("reason", "Insufficient spatial support or uncertainty.")})
        r = review("Registration is unavailable, not proof of loss. Independently identify the SAME physical printed lid landmarks p0,p1,p2 defined in context. Request fresh named depth points p0,p1,p2, choosing either current view. Historical projections are not detections. Return identity=exact only if all physical correspondences are unambiguous; otherwise ambiguous or unknown. Return rigid=intact only if they remain on the same intact box. Do not substitute camera-relative corners, predicted positions, or new arbitrary points.", {"identity": ["exact", "ambiguous", "unknown"], "rigid": ["intact", "changed", "unknown"]}, {"definitions": D["definitions"], "reference_points": D["P"], "reference_frame": D["reference_frame"], "last_observation": D.get("carry")})
        if r["parameters"]["identity"] != "exact" or r["parameters"]["rigid"] != "intact": stop("Unknown registration: no unambiguous independently measurable correspondence. No object transform fabricated.")
        B = points(r, ["p0", "p1", "p2"]); A = np.array(D["P"]); ac = A.mean(axis=0); bc = B.mean(axis=0)
        U, singular, Vt = np.linalg.svd((A-ac).T @ (B-bc)); R = Vt.T @ U.T
        if np.linalg.det(R) < 0: Vt[-1, :] *= -1; R = Vt.T @ U.T
        T = np.eye(4); T[:3, :3] = R; T[:3, 3] = bc - R @ ac
        residual = float(np.max(np.linalg.norm(geo.transform(A, T)-B, axis=1)))
        spread = np.linalg.svd(A-ac, compute_uv=False)
        log("landmark_registration", {"residual_m": residual, "reference_spread_m": spread.tolist(), "frame": r["frame_id"]})
        if residual > 0.0035 or spread[1] < 0.006: stop("Landmark correspondence is too uncertain or nearly collinear.")
        return {"P": B.tolist(), "T": T.tolist(), "u": max(0.003, residual+0.002), "frame": r["frame_id"], "source": "Independent corresponding RGB-D landmarks"}
    def retained(before, after, test=False):
        s = api.state(); err = float(geo.attachment_error(before["observation"]["P"], after["P"], before["state"], s))
        dh = np.array(s["tcp_position_world_m"]) - np.array(before["state"]["tcp_position_world_m"])
        do = np.mean(np.array(after["P"])-np.array(before["observation"]["P"]), axis=0)
        limit = min(0.012, tol+before["observation"]["u"]+after["u"]+0.002)
        log("retention", {"attachment_error_m": err, "limit_m": limit, "hand_motion_m": dh.tolist(), "object_motion_m": do.tolist(), "observation": after})
        if err > limit or (test and (dh[2] < 0.018 or do[2] < 0.014)): stop("Retention not established by independently observed object and actual hand motion.")
        D["carry"] = {"observation": after, "state": s}; save()
    def move(target, q, label, held=False, pinch=False, reserve=18):
        target = np.array(target); view_used = False
        for leg in range(16):
            s = api.state(); p = geo.pad_position(s); delta = target-p; distance = float(np.linalg.norm(delta))
            angle = 2*math.acos(min(1.0, abs(float(np.dot(s["tcp_quaternion_xyzw"], q)))))
            if distance <= tol and angle <= 0.05: return
            if s["budgets"]["gpt_remaining"] < (3 if D["phase"] == "released" else 5) or s["budgets"]["jev_remaining"] < reserve+4 or s["budgets"]["native_steps_remaining"] < 3*(reserve+4): stop("Reserved verification resources; unfinished motion: " + label)
            cap = 0.16 if label in ["high lateral approach", "vertical approach over measured source", "lift above measured bowl lip", "transfer above bowl opening"] else 0.06
            waypoint = p + delta * min(1.0, cap/max(distance, 0.000001))
            f = {"obstruction": ["external_obstacle", "none_visible", "undetermined"], "visibility": ["local_visible", "self_occluded", "unobserved"], "basis": ["observed_local_space", "own_envelope_and_measured_local_geometry", "none"], "up_view": ["justified", "not_justified"]}
            if pinch: f["pinch_access"] = ["visible_fit", "blocked", "unknown"]
            r = review("Assess ONLY the proposed bounded local action in context, not an entire later corridor. obstruction distinguishes an observed external obstacle from none visible and undetermined. visibility distinguishes visible local space, robot/held-box self-occlusion, and unobserved external space. Empty air in an observable open workspace need not yield depth returns. Unobserved means an unresolved external region relevant to THIS action, not missing certification or self-occlusion. basis must identify actual current local evidence supporting this short action; own-envelope basis requires measured local support geometry and no indicated external interference, not assumed clearance. Unknown is not free space; self-occlusion alone is not an external obstacle. up_view=justified only if an 18 mm vertical upward view-changing action has its own observable local justification. If pinch_access is requested, visible_fit means actual open finger faces straddle the box's opposing short sides with lateral entry space; pose attainment alone is not fit.", f, {"phase": label, "from_pad": p.tolist(), "next_pad": waypoint.tolist(), "quaternion": q, "own_geometry": s["own_geometry"], "geometry": D["geometry"], "carry": D.get("carry")})
            a = r["parameters"]
            if a["obstruction"] == "external_obstacle": stop("Observed external obstruction for " + label)
            justified = a["obstruction"] == "none_visible" and a["visibility"] != "unobserved" and a["basis"] != "none"
            if pinch and a["pinch_access"] != "visible_fit": stop("Actual open-finger entry clearance is not established.")
            if not justified:
                if view_used or a["up_view"] != "justified": stop("Local evidence gap for " + label + ": " + str(a))
                waypoint = p + np.array([0, 0, 0.018]); view_used = True
            command_q = q if justified else s["tcp_quaternion_xyzw"]
            calls = min(12, api.state()["budgets"]["jev_remaining"]-reserve, api.state()["budgets"]["native_steps_remaining"]//3-reserve)
            rc = api.drive(waypoint.tolist(), command_q, "keep", questions, features={"phase": label, "local_evidence": a, "waypoint_pad_world_m": waypoint.tolist(), "not_a_collision_certificate": True}, max_calls=calls, tool_point="pad_center", translation_limit=0.02, rotation_limit=0.08, steps=3, position_tolerance=tol, rotation_tolerance=0.05)
            log("motion", {"phase": label, "status": rc["status"], "error_m": rc["position_error_m"], "lease_calls": rc["lease_calls"]})
            if rc["status"] == "stalled": stop("Stalled motion; do not push contact again.")
            if rc["status"] not in ["reached", "lease_exhausted"]: stop("Unexpected drive result.")
            if rc["status"] == "lease_exhausted": stop("Local lease incomplete; preserve actual pose rather than consume the route bound on arbitrarily small progress.")
            if held: retained(D["carry"], register())
        stop("Finite route bound exhausted: " + label)
    try:
        records = api.recall()
        if any(r["key"] == "cream_method" for r in records):
            D.update(api.recall("cream_method")["value"])
            r = review("This is a repair in the same physical episode. Revalidate the saved bowl and table reference identities and lack of displacement. source_state must describe actual current cream cheese support, not the previous phase. Do not reopen a possibly held object.", {"references": ["unchanged", "changed", "unknown"], "source_state": ["supported_on_table", "in_hand", "released_at_bowl", "unknown"]}, D)
            a = r["parameters"]
            if a["references"] != "unchanged": stop("Saved support geometry needs fresh measurement; exact changed dependency is unresolved.")
            if a["source_state"] == "in_hand": D["phase"] = "closing"
            elif a["source_state"] == "released_at_bowl": D["phase"] = "released"
            elif a["source_state"] == "supported_on_table" and D["phase"] in ["ready", "approach"]: D["phase"] = "ready"
            else: stop("Repair cannot safely establish manipulation phase.")
        else:
            f = {"object": ["supported_rectangular_box", "other", "unknown"], "corners_visible": ["yes", "no", "unknown"], "top_camera": camera_names, "corners": array(pixel, 4), "corner_definitions": array("string", 4), "landmark_definitions": array("string", 3), "rim_identity": ["inner_lip", "unknown"], "rim_camera": camera_names, "rim_pixels": array(pixel, 6), "patch_camera": camera_names, "patch": array(pixel, 3, 12), "patch_identity": ["box_only", "unknown"]}
            r = review("Task: put the cream cheese box into the bowl. Acquire geometry, not a motion recipe. object=supported_rectangular_box requires visible tabletop support and an intact box with planar horizontal lid. Give four truly visible lid corner pixels cyclically in corners, in top_camera, and persistent physical corner_definitions anchored to printing/faces, not screen directions. Request named region lid strictly inside its planar top and region table on nearby bare supporting tabletop, with explicit camera, box and stride=4. Request three noncollinear named interior printed-feature depth points p0,p1,p2 spread across the lid; give precise persistent landmark_definitions. Give rim_camera and six rim_pixels distributed around the bowl's INNER solid lip, avoiding mixed-depth edges; the program will depth-sample these with radius 1. rim_identity must confirm these truly bound the opening. Give a textured interior box-only patch polygon and its own patch_camera. Never infer hidden corners or a hidden underside.", f)
            a = r["parameters"]
            if a["object"] != "supported_rectangular_box" or a["corners_visible"] != "yes" or a["rim_identity"] != "inner_lip": stop("Required visible object/support/opening identity missing.")
            fits = {}
            for name in ["table", "lid"]:
                if name not in r["regions"]: stop("Missing " + name + " region: " + str(r["measurement_errors"]))
                cloud = r["regions"][name]["world_m"]
                if len(cloud) < 12: stop("Too few surface samples for " + name)
                fits[name] = plain(geo.plane(cloud))
                if fits[name]["rms_m"] > 0.0025 or fits[name]["coefficients"][2] < 0.98: stop("Nonplanar or nonhorizontal " + name + ": " + str(fits[name]))
            if np.dot(fits["table"]["coefficients"][:3], fits["lid"]["coefficients"][:3]) < 0.995: stop("Lid and supporting plane are not sufficiently parallel.")
            C = np.array([api.plane_point(a["top_camera"], px, fits["lid"]["coefficients"])["world_m"] for px in a["corners"]])
            P = points(r, ["p0", "p1", "p2"])
            if np.max(np.abs(P @ np.array(fits["lid"]["coefficients"][:3])+fits["lid"]["coefficients"][3])) > 0.004: stop("Printed landmarks inconsistent with measured lid.")
            rim_points = []
            for i, px in enumerate(a["rim_pixels"]):
                try: rim_points.append(api.point(a["rim_camera"], px, radius=1)["world_m"])
                except Exception as e: log("rim_measurement_error", {"index": i, "error": str(e)})
            if len(rim_points) < 5: stop("Insufficient valid measured bowl lip coverage.")
            B = np.array(rim_points); bp = plain(geo.plane(B)); circle = plain(geo.circle_xy(B))
            log("geometry_fits", {"surfaces": fits, "rim_plane": bp, "circle": circle})
            if bp["rms_m"] > 0.003 or bp["coefficients"][2] < 0.98 or circle["max_radial_error_m"] > 0.004 or circle["largest_angular_gap_rad"] > math.pi: stop("Bowl lip does not support a sufficiently observed horizontal opening.")
            edges = np.roll(C, -1, axis=0)-C; lengths = np.linalg.norm(edges, axis=1)
            if max(abs(float(np.dot(edges[i], edges[(i+1)%4])))/(lengths[i]*lengths[(i+1)%4]) for i in range(4)) > 0.15: stop("Measured corners do not support rectangular box extent.")
            center = C.mean(axis=0); n = np.array(fits["table"]["coefficients"]); table_z = -(n[0]*center[0]+n[1]*center[1]+n[3])/n[2]; height = float(center[2]-table_z)
            sigma = 0.002+max(fits["lid"]["rms_m"], fits["table"]["rms_m"], circle["rms_m"]); margin = tol+2*sigma
            radius = float(max(np.linalg.norm(c[:2]-center[:2]) for c in C))
            if height <= 2*sigma or radius+margin >= circle["radius_m"]: stop("Measured extent/placement infeasible: " + str({"height": height, "box_radius": radius, "mouth_radius": circle["radius_m"], "margin": margin}))
            short = edges[int(np.argmin(lengths))]; s = api.state(); R0 = geo.rotation(s["tcp_quaternion_xyzw"]); yaw = math.atan2(short[1], short[0])-math.atan2(R0[1,1], R0[0,1]); yaw = (yaw+math.pi/2)%math.pi-math.pi/2
            q = api.compose(s["tcp_quaternion_xyzw"], [0, 0, yaw]); R = geo.rotation(q); own = s["own_geometry"]; low = own["finger_low_offset_tool_m"]; high = own["finger_high_offset_tool_m"]
            envelope = np.array([[x,y,z] for x in [low[0],high[0]] for y in [low[1],high[1]] for z in [low[2],high[2]]])
            lowest = float(np.min(((envelope-np.array(own["pad_center_in_tool_m"])) @ R.T)[:,2])); halfpad = float(np.dot(np.abs(R[2,:]), own["pad_extent_in_tool_m"])/2)
            lower = table_z+(tol+sigma-float(np.min(((envelope-np.array(own["pad_center_in_tool_m"])) @ R.T) @ n[:3])))/n[2]; upper = center[2]+halfpad-min(0.006,height/4)-sigma; grasp_z = max(lower,min(center[2]-height*0.15,upper)); joint_span = abs(s["gripper_qpos_m"][0]-s["gripper_qpos_m"][1])
            log("grasp_geometry", {"height": height, "short_width": float(min(lengths)), "joint_span_not_inner_gap": joint_span, "pad_z_bounds": [lower,upper], "finger_low_relative_pad": lowest, "sigma": sigma})
            if lower > upper or min(lengths)+2*(tol+sigma) >= joint_span: stop("Measured finger/support/grasp bounds infeasible; joint span is only a necessary check, not contact evidence.")
            bottom = C.copy(); bottom[:,2] = -(bottom[:,0]*n[0]+bottom[:,1]*n[1]+n[3])/n[2]; V = np.concatenate([C, bottom])
            D.update({"phase": "ready", "P": P.tolist(), "V": V.tolist(), "C": C.tolist(), "definitions": a["landmark_definitions"], "corner_definitions": a["corner_definitions"], "reference_frame": r["frame_id"], "q": q, "grasp_z": grasp_z, "sigma": sigma, "geometry": {"table_plane": fits["table"]["coefficients"], "lid_plane": fits["lid"]["coefficients"], "box_height_from_supported_surfaces": height, "box_top": C.tolist(), "bowl_center_xy": circle["center_xy_m"], "bowl_rim_z": float(B[:,2].mean()), "bowl_radius": circle["radius_m"], "margin": margin, "frame": r["frame_id"]}})
            save()
            if a["patch_identity"] == "box_only":
                try:
                    t = api.track_init(a["patch_camera"], a["patch"]); handles.append(t["handle"]); log("patch_reference", t)
                except Exception as e: log("patch_init_failure", str(e))
            if not handles:
                r = review("Choose a DIFFERENT usable textured interior cream-cheese lid patch, preferably the other camera. Give camera and polygon; identity=box_only requires excluding fingers/background. This is one bounded replacement after insufficient patch features, not a repeat of the same ROI.", {"camera": camera_names, "polygon": array(pixel, 3, 12), "identity": ["box_only", "unknown"]}, {"definitions": D["definitions"]})
                if r["parameters"]["identity"] == "box_only":
                    try:
                        t = api.track_init(r["parameters"]["camera"], r["parameters"]["polygon"]); handles.append(t["handle"]); log("patch_reference", t)
                    except Exception as e: log("patch_init_failure", str(e))
        q = D["q"]; g = D["geometry"]
        if D["phase"] == "ready":
            obs = {"P": D["P"], "T": np.eye(4).tolist(), "u": D["sigma"], "frame": D["reference_frame"], "source": "Fresh initial measured landmarks"} if api.state()["frame_id"] == D["reference_frame"] else register()
            current = geo.transform(np.array(D["C"]), np.array(obs["T"])); center = current.mean(axis=0)
            if abs(center[2]-np.mean(np.array(D["C"])[:,2])) > 0.006: stop("Source support height changed; refresh geometry before approach.")
            save("approach"); p = geo.pad_position(api.state())
            move([center[0],center[1],max(p[2],center[2]+0.08)], q, "high lateral approach")
            move([center[0],center[1],center[2]+0.045], q, "vertical approach over measured source")
            obs = register(); current = geo.transform(np.array(D["C"]), np.array(obs["T"])); center = current.mean(axis=0)
            sides = np.roll(current,-1,axis=0)-current; side = sides[int(np.argmin(np.linalg.norm(sides,axis=1)))]
            if abs(float(np.dot(side/np.linalg.norm(side),geo.rotation(q)[:,1]))) < math.cos(0.10): stop("Current box yaw no longer matches the measured side-pinch alignment.")
            move([center[0],center[1],D["grasp_z"]], q, "descend to side pinch", pinch=True)
            obs = register(); D["baseline"] = {"observation": obs, "state": api.state()}; save("closing")
            pulse("close")
            r = review("Observe actual closure. contact=aligned_or_pinched permits a bounded retention-measurement lift but does not prove a grasp. uncertain is allowed only without an explicit miss or external obstruction. Do not require the full box outline: a visible printed patch is enough for subsequent motion registration. external must describe external interference, not self-occlusion.", {"contact": ["aligned_or_pinched", "definite_miss", "uncertain"], "external": ["none_visible", "observed", "unknown"]}, {"baseline": D["baseline"], "definitions": D["definitions"]})
            if r["parameters"]["contact"] == "definite_miss" or r["parameters"]["external"] != "none_visible": stop("Closure not suitable for a justified retention test; leave gripper unchanged.")
        if D["phase"] == "closing":
            if "baseline" not in D:
                D["baseline"] = {"observation": register(), "state": api.state()}; save()
            p = geo.pad_position(api.state()); move((p+[0,0,0.028]).tolist(), q, "short upward retention-measurement lift")
            obs = register(); retained(D["baseline"], obs, True); save("held")
        if D["phase"] == "held":
            obs = D["carry"]["observation"]; V = geo.transform(np.array(D["V"]), np.array(obs["T"])); p = geo.pad_position(api.state())
            move((p+[0,0,max(0,g["bowl_rim_z"]+0.05-float(V[:,2].min()))]).tolist(), q, "lift above measured bowl lip", held=True)
            V = geo.transform(np.array(D["V"]), np.array(D["carry"]["observation"]["T"])); p = geo.pad_position(api.state()); delta = np.array(g["bowl_center_xy"])-V[:4,:2].mean(axis=0)
            move((p+[delta[0],delta[1],0]).tolist(), q, "transfer above bowl opening", held=True)
            V = geo.transform(np.array(D["V"]), np.array(D["carry"]["observation"]["T"])); p = geo.pad_position(api.state())
            move((p+[0,0,g["bowl_rim_z"]+0.012-float(V[:,2].min())]).tolist(), q, "lower to short release height", held=True)
            V = geo.transform(np.array(D["V"]), np.array(D["carry"]["observation"]["T"])); radial = float(np.max(np.linalg.norm(V[:,:2]-np.array(g["bowl_center_xy"]),axis=1))); gap = float(V[:,2].min()-g["bowl_rim_z"])
            log("release_geometry", {"footprint_radius": radial, "available_radius": g["bowl_radius"]-g["margin"], "bottom_above_rim": gap})
            if radial >= g["bowl_radius"]-g["margin"] or gap < 0.003 or gap > 0.025: stop("Observed release geometry is not inside the measured opening at a short drop height.")
            r = review("Check the ACTUAL held box and bowl now. mouth=stationary_open_centered means the same bowl has not shifted, its mouth is unblocked, and the measured box footprint is over its interior rather than the rim. Do not claim success before release.", {"mouth": ["stationary_open_centered", "changed_or_blocked", "unknown"]}, {"geometry": g, "current_vertices": V.tolist(), "retention": D["carry"]})
            if r["parameters"]["mouth"] != "stationary_open_centered": stop("Release relation not currently supported.")
            save("releasing"); pulse("open"); save("released")
        if D["phase"] == "released":
            p = geo.pad_position(api.state()); move((p+[0,0,0.05]).tolist(), api.state()["tcp_quaternion_xyzw"], "post-release retreat and new view", reserve=3)
            r = review("Assess actual cream cheese after release, not intended position. relation=inside_bowl means physically seated/contained by the bowl interior, not merely overlapping in projection or balanced on its rim. support=resting means visibly supported, not falling. Request named point settled on a distinctive visible printed box landmark and provide its persistent definition for the next observation.", {"relation": ["inside_bowl", "on_rim", "outside", "unknown"], "support": ["resting", "unstable", "unknown"], "definition": {"type": "string", "maxLength": 400}}, {"task": "cream cheese into bowl", "geometry": g})
            first = points(r, ["settled"])[0]; first_frame = r["frame_id"]; pulse("keep", 2)
            r2 = review("After the acknowledged settling interval, assess the actual box/bowl relation and support again. Request named point settled on the SAME physical printed landmark defined in context, not the old projected pixel. identity=exact requires an unambiguous correspondence. A stopped robot is not evidence of object stability.", {"relation": ["inside_bowl", "on_rim", "outside", "unknown"], "support": ["resting", "unstable", "unknown"], "identity": ["exact", "ambiguous", "unknown"]}, {"definition": r["parameters"]["definition"], "previous_point": first.tolist(), "previous_frame": first_frame})
            second = points(r2, ["settled"])[0]; displacement = float(np.linalg.norm(second-first)); log("released_outcome", {"first": r["parameters"], "second": r2["parameters"], "landmark_motion_m": displacement, "frames": [first_frame,r2["frame_id"]]})
            good = r["parameters"]["relation"] == "inside_bowl" and r2["parameters"]["relation"] == "inside_bowl" and r2["parameters"]["support"] == "resting" and r2["parameters"]["identity"] == "exact" and displacement <= 0.006
            if good: save("done")
            return {"completion_proposed": bool(good), "evidence": evidence, "limitations": "Heuristic RGB-D uncertainty and local visual checks, not certified swept-volume clearance or official task success."}
        stop("Unresolved phase: " + D["phase"])
    except Exception as e:
        log("stopped", {"reason": str(e), "phase": D.get("phase", "uninitialized"), "policy": "No blind reopening, transform extrapolation, or repeated contact pushing."})
        return {"completion_proposed": False, "evidence": evidence}
